+    const candidatePath = pathById.get(id)!;
+    if (finish > totalDuration || (finish === totalDuration && comparePaths(candidatePath, criticalPath) < 0)) {
+      totalDuration = finish;
+      criticalPath = candidatePath;
+    }
+  }
